<script setup lang="ts">
import DecimalInput from "./DecimalInput.vue"
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { money, number } from '../api'
import type { CalculationInput, Competitor } from '../types'
import Icon from './Icon.vue'
import { marketSummary } from '../lib/research'
const props = defineProps<{ input: CalculationInput; competitors: Competitor[] }>(); const { t } = useI18n()
const summary = computed(() => marketSummary(props.competitors))
function add() { if (props.competitors.length < 8) props.competitors.push({ id: '', platform: 'Shopee', shop: '', price: '', sales: '0', rating: '0', url: '' }) }
function useRange() { props.input.marketMin = summary.value.min; props.input.marketMax = summary.value.max }
</script>
<template><section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="trend" /></span><div><h3>{{ t('marketRange') }}</h3><p>{{ t('marketHint') }}</p></div></div><div class="form-grid"><div class="field"><label>{{ t('marketMin') }}<span>{{ t('optional') }}</span></label><div class="input-unit"><span>Rp</span><DecimalInput v-model="input.marketMin" min="1" step="any" :aria-label="t('marketMin')" /></div></div><div class="field"><label>{{ t('marketMax') }}<span>{{ t('optional') }}</span></label><div class="input-unit"><span>Rp</span><DecimalInput v-model="input.marketMax" min="1" step="any" :aria-label="t('marketMax')" /></div></div></div></section>
 <section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="research" /></span><div><h3>{{ t('competitors') }} <span class="muted small-text">{{ competitors.length }} / 8</span></h3><p>{{ t('competitorsSub') }}</p></div><button class="btn secondary compact" :disabled="competitors.length >= 8" @click="add"><Icon name="plus" :size="16" />{{ t('addCompetitor') }}</button></div><div v-if="!competitors.length" class="inline-empty">{{ t('noCompetitors') }}</div><div v-for="(c,i) in competitors" :key="i" class="competitor-form"><div class="competitor-number">{{ String(i + 1).padStart(2, '0') }}</div><div class="form-grid competitor-grid"><div class="field"><label>{{ t('platform') }}</label><input v-model="c.platform" maxlength="100" :aria-label="`${t('platform')} ${i+1}`" /></div><div class="field"><label>{{ t('shop') }}</label><input v-model="c.shop" maxlength="200" :aria-label="`${t('shop')} ${i+1}`" /></div><div class="field"><label>{{ t('price') }}</label><DecimalInput v-model="c.price" min="0" step="any" :aria-label="`${t('price')} ${i+1}`" /></div><div class="field"><label>{{ t('sales') }}</label><DecimalInput v-model="c.sales" min="0" :aria-label="`${t('sales')} ${i+1}`" /></div><div class="field"><label>{{ t('rating') }}</label><DecimalInput v-model="c.rating" min="0" max="5" step="0.1" :aria-label="`${t('rating')} ${i+1}`" /></div><div class="field"><label>{{ t('url') }}<span>{{ t('optional') }}</span></label><input v-model="c.url" type="url" :aria-label="`${t('url')} ${i+1}`" /></div></div><button class="icon-btn" :aria-label="`${t('remove')} ${i+1}`" @click="competitors.splice(i,1)"><Icon name="close" :size="17" /></button></div><div v-if="competitors.length" class="competitor-summary"><div><span>{{ t('competitorRange') }}</span><strong>{{ money(summary.min) }} – {{ money(summary.max) }}</strong></div><div><span>{{ t('averagePrice') }}</span><strong>{{ money(summary.avg || null) }}</strong></div><div><span>{{ t('medianPrice') }}</span><strong>{{ money(summary.median || null) }}</strong></div><div><span>{{ t('totalSales') }}</span><strong>{{ number(summary.sales) }}</strong></div><div><span>{{ t('topShop') }}</span><strong>{{ summary.top }}</strong></div><div class="research-actions"><button class="btn secondary compact" :disabled="!summary.median" @click="input.price = summary.median">{{ t('testMedian') }}</button><button class="text-link" :disabled="!summary.count" @click="useRange">{{ t('useRange') }}<Icon name="arrow" :size="16" /></button></div><p class="muted small-text">{{ t('salesEvidenceHint') }}</p></div></section>
</template>
